#pragma once
#include <WiFiManager.h>
// Preserve the pinned vendor root's captive redirect and access timestamp.
class PortalWifiManager : public WiFiManager {
public:
  bool beginCustomRoot() {
    if (captivePortal()) return false;
    handleRequest();
    return true;
  }
};
