constexpr char kRsWifiPortalPage[] = R"LHPAGE(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lighthouse Bridge · Wi-Fi setup</title>%PORTAL_HEAD%</head><body><main class="wrap"><header class="portal-header"><div class="portal-brand"><span class="portal-mark" aria-hidden="true">◈</span><span>Lighthouse Bridge</span></div><select class="portal-language" id="portal-language" aria-label="Language"><option value="en">English</option><option value="de">Deutsch</option></select></header><h1 data-copy="title">Choose your connection.</h1><p class="portal-intro" data-copy="intro">Connect the bridge to your home Wi-Fi or use it directly without a router.</p><div class="portal-ssid"><span data-copy="ssid">Setup Wi-Fi</span><code id="setup-ssid">%SSID%</code></div><div class="portal-modes"><form action="/wifi" method="get"><button class="mode-card" type="submit"><span class="mode-icon" aria-hidden="true">⌂</span><span class="mode-copy"><span class="mode-title" data-copy="home">Home Wi-Fi</span><span class="mode-description" data-copy="homeHelp">For Alexa, Matter and your home network.</span></span><span class="mode-arrow" aria-hidden="true">→</span></button></form><form action="/local" method="get"><button class="mode-card" type="submit"><span class="mode-icon" aria-hidden="true">↔</span><span class="mode-copy"><span class="mode-title">Local Mode</span><span class="mode-description" data-copy="localHelp">Connect directly to the bridge, without a router.</span></span><span class="mode-arrow" aria-hidden="true">→</span></button></form></div><div class="portal-secondary"><form action="/info" method="get"><button type="submit" data-copy="info">Device info</button></form><form action="/exit" method="get"><button type="submit" data-copy="exit">Leave setup</button></form></div><p class="portal-note" data-copy="note">Your station assignments and existing Matter pairings stay saved.</p></main><script>
const copy={en:{title:'Choose your connection.',intro:'Connect the bridge to your home Wi-Fi or use it directly without a router.',ssid:'Setup Wi-Fi',home:'Home Wi-Fi',homeHelp:'For Alexa, Matter and your home network.',localHelp:'Connect directly to the bridge, without a router.',info:'Device info',exit:'Leave setup',note:'Your station assignments and existing Matter pairings stay saved.',language:'Language'},de:{title:'Wie möchtest du verbinden?',intro:'Verbinde die Bridge mit deinem Heim-WLAN oder nutze sie direkt ohne Router.',ssid:'Setup-WLAN',home:'Heim-WLAN',homeHelp:'Für Alexa, Matter und dein Heimnetz.',localHelp:'Direkt mit der Bridge verbinden, ohne Router.',info:'Geräteinfo',exit:'Setup verlassen',note:'Deine Stationszuordnungen und bestehenden Matter-Kopplungen bleiben gespeichert.',language:'Sprache'}};
function portalLanguage(value,save=false){const lang=value==='de'?'de':'en';document.documentElement.lang=lang;document.getElementById('portal-language').value=lang;document.getElementById('portal-language').setAttribute('aria-label',copy[lang].language);document.querySelectorAll('[data-copy]').forEach(node=>node.textContent=copy[lang][node.dataset.copy]);document.title='Lighthouse Bridge · '+(lang==='de'?'WLAN-Setup':'Wi-Fi setup');if(save)try{localStorage.setItem('lighthouse-bridge.language',lang);}catch(_){}}
let saved;try{saved=localStorage.getItem('lighthouse-bridge.language');}catch(_){}portalLanguage(saved==='en'||saved==='de'?saved:navigator.language.startsWith('de')?'de':'en');document.getElementById('portal-language').addEventListener('change',event=>portalLanguage(event.target.value,true));
</script></body></html>)LHPAGE";
